#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use a row pointer (Li) to avoid repeated 2D indexing into L.
 *  - Hoist the (i + n + 1) part of the expression out of the inner loop.
 *  - Keep all arithmetic that was originally done in integer type in
 *    integer type to preserve exact semantics.
 *  - Optionally parallelizable: outer loop over i has no cross-iteration
 *    dependencies (OpenMP pragma added but harmless without -fopenmp).
 */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* L, x, and b do not alias in the benchmark setup, so using a row
   * pointer improves locality and reduces address arithmetic.
   */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Li = L[i];

      x[i] = (DATA_TYPE)-999;
      b[i] = (DATA_TYPE)i;

      /* Original formula:
       *   L[i][j] = (DATA_TYPE) (i + n - j + 1) * 2 / n;
       *
       * All operations were in 'int' before the cast, so we keep
       * that property exactly, only reorganizing as:
       *   base = i + n + 1;
       *   t    = base - j;
       *   v    = (t * 2) / n;
       *   L[i][j] = (DATA_TYPE)v;
       */
      int base = i + n + 1;
      for (j = 0; j <= i; j++)
      {
        int t = base - j;
        int v = (t * 2) / n;  /* still pure integer arithmetic */
        Li[j] = (DATA_TYPE)v;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * This performs a forward substitution on a lower-triangular system:
 *
 *   for i = 0..n-1:
 *     x[i] = ( b[i] - sum_{j=0..i-1} L[i][j] * x[j] ) / L[i][i]
 *
 * Optimizations:
 *  - Use a scalar accumulator 'sum' instead of repeatedly updating x[i]
 *    inside the inner loop; this keeps the running value in a register
 *    and clarifies the pattern as a dot product.
 *  - Use a row pointer 'Li' for L[i] to reduce address computation and
 *    improve cache locality.
 *  - Read the diagonal element once per row and perform a single
 *    division per outer iteration.
 *  - Mark 'b' as const in the interface: it is read-only in the kernel.
 *
 * Note: The outer loop over i is inherently sequential due to data
 * dependencies between x[i] and x[0..i-1]; we therefore do not attempt
 * to parallelize it. The transformation is algebraically identical
 * to the original code for all inputs.
 */
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    const DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *Li = L[i];     /* Pointer to current row of L */
      DATA_TYPE sum = b[i];     /* Accumulator for the dot product */

      /* Compute sum = b[i] - sum_{j=0..i-1} L[i][j] * x[j] */
      for (j = 0; j < i; j++)
        sum -= Li[j] * x[j];

      /* Final division by the diagonal element. Kept as a division
       * rather than precomputing an inverse to preserve behavior for
       * arbitrary matrices L (even though the provided initializer
       * generates a constant diagonal).
       */
      sum /= Li[i];

      x[i] = sum;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
