  /* Local restrict-qualified aliases to help the compiler
     assume no aliasing between L, x, and b. */
  DATA_TYPE (*restrict L_)[n] = L;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict b_ = b;

  /* Common multiplicative factor: (2.0 / n). */
  const DATA_TYPE factor = (DATA_TYPE)2 / (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Li = L_[i];

      x_[i] = (DATA_TYPE)-999;
      b_[i] = (DATA_TYPE)i;

      /* Only the lower triangular part (including diagonal) is initialized. */
      for (j = 0; j <= i; j++)
        {
          /* Original formula:
             L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
             Algebraically equivalent rewritten as:
             L[i][j] = (DATA_TYPE)(i + n - j + 1) * (2.0 / n);
             Hoisting (2.0 / n) out of the loop saves a division
             and improves throughput. */
          Li[j] = (DATA_TYPE)(i + n - j + 1) * factor;
        }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

