  for (i = 0; i < _PB_N; i++)
    {
      /* Accumulator for the inner product sum_{j < i} L[i][j] * x[j]. */
      DATA_TYPE sum = (DATA_TYPE)0;
      DATA_TYPE *restrict Li = L_[i];

      int j;

      /* Inner product of the i-th row prefix with x[0..i-1].
         Using a separate accumulator instead of repeatedly updating x[i]
         enables better optimization and vectorization.
         The OpenMP 'simd' directive is a hint to the compiler; it does
         not require linking with an OpenMP runtime if -fopenmp is not used. */
#pragma omp simd reduction(+:sum)
      for (j = 0; j < i; j++)
