/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Use local `restrict` pointers to the input arrays to eliminate
 *    potential aliasing and help the compiler keep values in registers.
 *  - Accumulate the running value of x[i] in a scalar `sum` instead of
 *    repeatedly writing back to x[i] inside the inner loop. This preserves
 *    the exact operation order: the same sequence of subtractions is
 *    performed, just into a register rather than into memory.
 *  - Access each row of L via a row pointer `Li` (i.e., L[i]) to reduce
 *    index arithmetic and improve cache locality.
 *  - Optionally unroll the inner loop by a constant factor (default 4)
 *    while maintaining the same left-to-right evaluation order of the
 *    floating-point operations.
 *
 * Importantly, the order of floating-point operations is not changed,
 * so numerical results match the original scalar implementation.
 */
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  (void)n; /* n is kept for interface compatibility; _PB_N is used below. */
  int i;

  /* Create local restrict-qualified aliases. These promise to the compiler
   * that L, x, and b do not overlap in memory, which is true for this
   * benchmark and enables better optimization.
   */
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict b_ = b;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Pointer to the i-th row of L. This improves spatial locality and
       * avoids recomputing the row base address inside the inner loop.
       */
      DATA_TYPE *restrict Li = L[i];

      /* Start from b[i], as in the original code (x[i] = b[i]; then
       * successive subtractions). We accumulate into a scalar to keep
       * the value in a register; this does not change the sequence of
       * floating-point operations.
       */
      DATA_TYPE sum = b_[i];

#if TRISOLV_INNER_UNROLL == 4
      /* Manually unrolled inner loop by a factor of 4.
       *
       * The original loop was:
       *   for (j = 0; j < i; j++)
       *     x[i] -= L[i][j] * x[j];
       *
       * Here we do:
       *   sum -= Li[0] * x_[0];
       *   sum -= Li[1] * x_[1];
       *   ...
       * in strictly increasing j order, one subtraction per statement.
       * This preserves the exact evaluation order while reducing loop
       * overhead and giving the compiler more room to optimize.
       */
      int j = 0;
      int limit = i & ~3; /* largest multiple of 4 <= i */

      for (; j < limit; j += 4)
        {
          sum -= Li[j]   * x_[j];
          sum -= Li[j+1] * x_[j+1];
          sum -= Li[j+2] * x_[j+2];
          sum -= Li[j+3] * x_[j+3];
        }

      /* Handle remaining iterations (if i is not a multiple of 4). */
      for (; j < i; ++j)
        {
          sum -= Li[j] * x_[j];
        }
#else
      /* Baseline inner loop (no manual unrolling). */
      int j;
      for (j = 0; j < i; j++)
        {
          sum -= Li[j] * x_[j];
        }
#endif

      /* Final division matches the original:
       *   x[i] = x[i] / L[i][i];
       * but applied to the accumulated sum. This is still one division
       * per row; we do not replace it with a multiplication by a
       * reciprocal to maintain strict IEEE-754 semantics.
       */
      x_[i] = sum / Li[i];
    }
#pragma endscop

}


